output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves are on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_hand_aisle",
    "text": "A shopper must not push a cart from a wide area into a single-file hand-shopping aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouth",
    "text": "If a cart is put down temporarily, it may only be parked at the mouth of a narrow hand-shopping aisle.",
    "abstraction": {
      "state_properties": {
        "handAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "handAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart to enter a hand-shopping aisle, the shopper is obliged to retrieve a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "handAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "handAisleMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "handAisleMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "interact_only_at_service_or_shelf",
    "text": "Interactions should occur only at cart-service points or while adjacent to a shelf.",
    "abstraction": {
      "state_properties": {
        "cartServicePoint": {
          "or": [
            "at(1,7)",
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "validInteractionLocation": {
          "or": [
            "cartServicePoint",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "validInteractionLocation"
          }
        ]
      }
    }
  },
  {
    "id": "known_product_faces_only",
    "text": "Shelf interactions are allowed only at recognized product-facing shelf positions, including different accessible faces of the same shelf.",
    "abstraction": {
      "state_properties": {
        "a1Face": {
          "and": [
            "at(3,1)",
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "a2Face": {
          "and": [
            "at(6,1)",
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "s1Face": {
          "or": [
            {
              "and": [
                "at(6,6)",
                "shelfN"
              ]
            },
            {
              "and": [
                "at(6,4)",
                "shelfS"
              ]
            },
            {
              "and": [
                "at(7,5)",
                "shelfW"
              ]
            }
          ]
        },
        "s2Face": {
          "and": [
            "at(9,6)",
            "shelfN"
          ]
        },
        "knownProductFace": {
          "or": [
            "a1Face",
            "a2Face",
            "s1Face",
            "s2Face"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "adjShelf",
          {
            "not": "knownProductFace"
          }
        ]
      }
    }
  },
  {
    "id": "hand_shelves_without_cart",
    "text": "Shelf interactions inside single-file hand-shopping aisles must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "open_shelf_shopping_requires_cart",
    "text": "Shelf interactions in cart-accessible open aisles should be performed with the cart present.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfAisle": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfAisle",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
